// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(c).call(abi.encodeWithSignature("owner()")));
        try c.setOwner(newOwner) returns (bool success) {
            assertTrue(success);
        } catch {
            // Revert means the call failed for other reasons, not our concern.
            assertTrue(true);
        }
    }
}
